create table xxventuri.crm_leads_t (
    lead_id                  number,
    first_name               varchar2(100 char) not null enable,
    last_name                varchar2(100 char) not null enable,
    company                  varchar2(200 char) not null enable,
    job_title                varchar2(100 char),
    email                    varchar2(255 char),
    phone                    varchar2(50 char),
    lead_source              varchar2(50 char),
    lead_status              varchar2(20 char) default 'NEW' not null enable,
    rating                   varchar2(20 char),
    owner_id                 number not null enable,
    converted_flag           char(1 byte) default 'N' not null enable,
    converted_account_id     number,
    converted_contact_id     number,
    converted_opportunity_id number,
    converted_date           date,
    status_code              varchar2(20 char) default 'ACTIVE' not null enable,
    row_version              number default 0 not null enable,
    created_by               varchar2(100 char) not null enable,
    created_date             timestamp(6) not null enable,
    updated_by               varchar2(100 char) not null enable,
    updated_date             timestamp(6) not null enable
);

alter table xxventuri.crm_leads_t
    add constraint crm_leads_converted_flag_chk
        check ( converted_flag in ( 'Y', 'N' ) ) enable;

alter table xxventuri.crm_leads_t
    add constraint crm_leads_pk primary key ( lead_id )
        using index enable;

alter table xxventuri.crm_leads_t
    add constraint crm_leads_status_chk
        check ( status_code in ( 'ACTIVE', 'INACTIVE' ) ) enable;

alter table xxventuri.crm_leads_t
    add constraint crm_leads_status_chk2
        check ( lead_status in ( 'NEW', 'CONTACTED', 'QUALIFIED', 'UNQUALIFIED', 'CONVERTED' ) ) enable;


